import { getAllBlogPostsMeta } from '@/lib/blog-posts-meta'
import homepageNews from '@/lib/news-homepage.json' with { type: 'json' }

// Shared "when did the content last change" dates.
//
// Derived from real publication dates (or stored page dates) rather than build
// time, so a no-op rebuild does not churn the values and they mean something to
// crawlers. The sitemap reads its <lastmod> values from here.
//
// Reads from `news-homepage.json` (generated by `tools/emit-homepage-news.mjs`,
// newest-first top-12 slice) instead of the full 200-item `news-items.json` catalog
// so layout/sitemap callers never bundle the ~700 KB news archive.
//
// JsonLd.tsx is a client module, so a `new Date()` there is baked into the
// exported HTML at build time and re-evaluated at hydration — a guaranteed
// hydration mismatch. These helpers are the deterministic replacement.

/** A post's effective last-change date: the later of `date` and `lastModified`. */
function postDate(post: { date: string; lastModified?: string }): number {
  // Not `lastModified ?? date`: one post carries a `lastModified` that predates
  // its own `date`, and `??` would silently discard the newer of the two.
  const published = new Date(post.date).getTime()
  const modified = post.lastModified ? new Date(post.lastModified).getTime() : 0
  return Math.max(published, modified)
}

/** Newest effective date across blog posts. */
export function getLatestBlogDate(): Date {
  const posts = getAllBlogPostsMeta('en')
  return posts.length ? new Date(Math.max(...posts.map(postDate))) : new Date()
}

/** Date of the newest news item, or undefined when there are none. */
export function getLatestNewsDate(): string | undefined {
  let latest: string | undefined
  for (const item of homepageNews.items) {
    if (!latest || item.date > latest) {
      latest = item.date
    }
  }
  return latest
}

/**
 * Stored last-change dates for pages without their own content dates. Update the
 * entry when the page, or a section it renders, changes in a way readers would notice.
 */
export const PAGE_LAST_MODIFIED = {
  home: '2026-11-27',
  about: '2026-11-25',
  research: '2026-11-25',
  // Keep in sync with `UPDATED` in `src/components/LegalContent.tsx`.
  legal: '2026-11-27',
} as const

/**
 * The homepage's last-modified date: its own stored date or the newest blog post,
 * whichever is later (the homepage lists the latest posts). News is deliberately
 * left out: the concise homepage doesn't show it, and a lastmod that moves with every
 * daily news update teaches crawlers to ignore this sitemap's dates.
 */
export function getHomepageDate(): Date {
  return new Date(Math.max(new Date(PAGE_LAST_MODIFIED.home).getTime(), getLatestBlogDate().getTime()))
}
